import heapq

def solve(x):
    n, src, dst, start, lay, edges = x['n'], x['src'], x['dst'], x['start'], x['lay'], x['edges']

    # Initialize graph
    graph = [[] for _ in range(n)]
    for u, v, first, period, last, duration in edges:
        graph[u].append((v, first, period, last, duration))

    # Priority queue for Dijkstra's algorithm
    pq = [(start, src, 0)]
    # Dictionary to store the earliest arrival time and whether the pass was used
    earliest_arrival = [[None, None] for _ in range(n)]
    earliest_arrival[src] = [start, 0]

    while pq:
        current_time, current_node, pass_used = heapq.heappop(pq)

        if current_node == dst:
            return [current_time, pass_used]

        if current_time > earliest_arrival[current_node][0]:
            continue

        for neighbor, first, period, last, duration in graph[current_node]:
            for k in range((last - first) // period + 1):
                departure = first + k * period
                if departure >= current_time + lay[current_node]:
                    arrival = departure + duration
                    if earliest_arrival[neighbor][0] is None or arrival < earliest_arrival[neighbor][0]:
                        earliest_arrival[neighbor] = [arrival, pass_used]
                        heapq.heappush(pq, (arrival, neighbor, pass_used))
                    if pass_used == 0 and earliest_arrival[neighbor][0] is not None and earliest_arrival[neighbor][1] == 0:
                        earliest_arrival[neighbor][1] = 1
                        heapq.heappush(pq, (arrival, neighbor, 1))

    return [None, None]

