from collections import defaultdict
from heapq import heappop, heappush

def solve(x):
    n, src, dst, start, lay, edges = x['n'], x['src'], x['dst'], x['start'], x['lay'], x['edges']

    graph = defaultdict(list)
    for u, v, first, period, last, duration in edges:
        graph[u].append((v, first, period, last, duration))

    def dijkstra(start):
        pq = [(start, 0, 0)]
        dist = defaultdict(lambda: float('inf'))
        dist[(start, 0)] = 0
        pass_used = defaultdict(lambda: float('inf'))
        pass_used[(start, 0)] = 0

        while pq:
            arrival, u, k = heappop(pq)
            if u == dst:
                return arrival, pass_used[(u, k)]
            if arrival > dist[(u, k)]:
                continue
            for v, first, period, last, duration in graph[u]:
                next_arrival = max(arrival, first + k * period)
                if next_arrival > last:
                    continue
                next_arrival += duration
                if next_arrival >= arrival + lay[u]:
                    if dist[(v, k)] > next_arrival:
                        dist[(v, k)] = next_arrival
                        heappush(pq, (next_arrival, v, k))
                if k == 0 and pass_used[(v, 1)] > next_arrival:
                    pass_used[(v, 1)] = next_arrival
                    heappush(pq, (next_arrival, v, 1))

        return float('inf'), float('inf')

    earliest_arrival, pass_used = dijkstra(start)
    return [earliest_arrival if earliest_arrival != float('inf') else None, pass_used if pass_used != float('inf') else None]

